import React, { useState, useRef } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [userId, setUserId] = useState("");
  const [qrData, setQrData] = useState("");
  const [photo, setPhoto] = useState("");
  const [showPayment, setShowPayment] = useState(false);
  const [utrNumber, setUtrNumber] = useState("");
  const [verifying, setVerifying] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  // ── Your UPI ID ──────────────────────────────────────────
  const YOUR_UPI_ID = "arunsekar664@okaxis";
  const AMOUNT = "1";
  const PAYEE_NAME = "CollegeEvent";
  // ─────────────────────────────────────────────────────────

  /* =============================
     UPI DEEP LINKS
  ============================= */
  const upiParams = `pa=${YOUR_UPI_ID}&pn=${PAYEE_NAME}&am=${AMOUNT}&cu=INR&tn=EventRegistration`;

  const deepLinks = {
    gpay: `tez://upi/pay?${upiParams}`,
    phonepe: `phonepe://pay?${upiParams}`,
    paytm: `paytmmp://pay?${upiParams}`,
  };

  const openApp = (app) => {
    window.location.href = deepLinks[app];
  };

  /* =============================
     INPUT CHANGE
  ============================= */
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* =============================
     SHOW PAYMENT SCREEN
  ============================= */
  const handleShowPayment = (e) => {
    e.preventDefault();
    setShowPayment(true);
  };

  /* =============================
     VERIFY UTR + REGISTER
  ============================= */
  const verifyAndRegister = async () => {
    if (!utrNumber.trim()) {
      alert("Please enter your UTR / Transaction ID");
      return;
    }

    setVerifying(true);

    try {
      const res = await axios.post("http://localhost:5000/verify-utr", {
        utrNumber: utrNumber.trim(),
        amount: AMOUNT,
        ...formData,
        photo,
      });

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        alert("Payment Verified! Registration Successful.");
      } else {
        alert(res.data.message || "UTR verification failed. Please try again.");
      }
    } catch (err) {
      alert("Verification failed. Please contact support.");
    } finally {
      setVerifying(false);
    }
  };

  /* =============================
     OPEN CAMERA
  ============================= */
  const openCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: false,
      });
      streamRef.current = stream;
      videoRef.current.srcObject = stream;
      videoRef.current.play();
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
     CAPTURE PHOTO
  ============================= */
  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0);
    const image = canvas.toDataURL("image/png");
    setPhoto(image);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
    }
  };

  /* =============================
     DOWNLOAD ID CARD
  ============================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "Event_ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  return (
    <div>
      <Navbar />

      <div style={{ textAlign: "center", padding: "20px" }}>
        <h2>Event Registration</h2>

        {/* ── STEP 1: FORM ── */}
        {!showPayment && !qrData && (
          <form onSubmit={handleShowPayment}>
            <input
              name="name"
              placeholder="Name"
              onChange={handleChange}
              required
            />
            <br /><br />

            <input
              name="college_name"
              placeholder="College Name"
              onChange={handleChange}
              required
            />
            <br /><br />

            <input
              name="phone"
              placeholder="Phone"
              onChange={handleChange}
              required
            />
            <br /><br />

            <input
              name="email"
              placeholder="Email"
              onChange={handleChange}
              required
            />
            <br /><br />

            <h3>Selected Event: {eventName}</h3>

            <button type="submit">Proceed to Pay ₹{AMOUNT}</button>
          </form>
        )}

        {/* ── STEP 2: PAYMENT SCREEN ── */}
        {showPayment && !qrData && (
          <div>
            <h3>Pay ₹{AMOUNT} using UPI</h3>
            <p>Click any app below to pay directly:</p>

            {/* Deep Link Buttons */}
            <div style={{ display: "flex", justifyContent: "center", gap: "16px", flexWrap: "wrap", marginBottom: "24px" }}>

              {/* GPay */}
              <button
                onClick={() => openApp("gpay")}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "8px",
                  padding: "12px 24px",
                  backgroundColor: "#1a73e8",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  fontSize: "16px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/thumb/f/f2/Google_Pay_Logo.svg/512px-Google_Pay_Logo.svg.png"
                  alt="GPay"
                  width="28"
                  height="28"
                  style={{ objectFit: "contain" }}
                />
                GPay
              </button>

              {/* PhonePe */}
              <button
                onClick={() => openApp("phonepe")}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "8px",
                  padding: "12px 24px",
                  backgroundColor: "#5f259f",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  fontSize: "16px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/PhonePe_Logo.svg/512px-PhonePe_Logo.svg.png"
                  alt="PhonePe"
                  width="28"
                  height="28"
                  style={{ objectFit: "contain" }}
                />
                PhonePe
              </button>

              {/* Paytm */}
              <button
                onClick={() => openApp("paytm")}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: "8px",
                  padding: "12px 24px",
                  backgroundColor: "#00BAF2",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  fontSize: "16px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                <img
                  src="https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Paytm_Logo_%28standalone%29.svg/512px-Paytm_Logo_%28standalone%29.svg.png"
                  alt="Paytm"
                  width="28"
                  height="28"
                  style={{ objectFit: "contain" }}
                />
                Paytm
              </button>
            </div>

            <hr style={{ margin: "20px auto", width: "60%" }} />

            {/* UTR Entry */}
            <p style={{ fontWeight: "bold" }}>
              After payment, enter your UTR / Transaction ID:
            </p>
            <p style={{ fontSize: "13px", color: "#666" }}>
              (Find it in your payment app → Transaction History → Transaction ID / UTR)
            </p>

            <input
              type="text"
              placeholder="Enter UTR / Transaction ID"
              value={utrNumber}
              onChange={(e) => setUtrNumber(e.target.value)}
              style={{
                padding: "10px",
                fontSize: "15px",
                width: "280px",
                borderRadius: "6px",
                border: "1px solid #ccc",
                marginBottom: "16px",
              }}
            />
            <br />

            <button
              onClick={verifyAndRegister}
              disabled={verifying}
              style={{
                padding: "10px 28px",
                backgroundColor: "#28a745",
                color: "white",
                border: "none",
                borderRadius: "8px",
                fontSize: "16px",
                cursor: verifying ? "not-allowed" : "pointer",
                fontWeight: "bold",
              }}
            >
              {verifying ? "Verifying..." : "Verify & Get ID Card"}
            </button>

            <br /><br />
            <button
              onClick={() => setShowPayment(false)}
              style={{ background: "none", border: "none", color: "#888", cursor: "pointer", textDecoration: "underline" }}
            >
              ← Back to Form
            </button>
          </div>
        )}

        {/* ── STEP 3: QR + CAMERA ── */}
        {qrData && (
          <div>
            <h3>Your QR Code</h3>
            <QRCode value={qrData.toString()} size={200} />
            <br /><br />

            <button onClick={openCamera}>Open Camera</button>
            <br /><br />

            <video
              ref={videoRef}
              width="320"
              height="240"
              style={{ border: "2px solid black" }}
            />
            <br /><br />

            <button onClick={capturePhoto}>Capture Photo</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ── STEP 4: ID CARD ── */}
        {photo && (
          <div style={{ marginTop: "30px" }}>
            <div
              ref={idCardRef}
              style={{
                border: "2px solid black",
                width: "300px",
                margin: "auto",
                padding: "15px",
                borderRadius: "10px",
              }}
            >
              <h3>College Event ID Card</h3>
              <p>Name : {formData.name}</p>
              <p>User ID : {userId}</p>
              <p>Event : {eventName}</p>
              <QRCode value={qrData.toString()} size={120} />
              <br /><br />
              <img src={photo} alt="User" width="120" />
            </div>
            <br />
            <button onClick={downloadCard}>Download ID Card</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
